import os
import sys
import json
from datetime import datetime

def parse_tsv(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    lines = content.splitlines()
    header_idx = None
    for i, line in enumerate(lines):
        if line.startswith('attribute\t') or line == 'attribute':
            header_idx = i
            break
    if header_idx is None:
        return {}
    headers = lines[header_idx].split('\t')
    records = [{} for _ in range(len(headers) - 1)]
    for line in lines[header_idx + 1:]:
        if not line.strip():
            continue
        fields = line.split('\t')
        attr = fields[0]
        for j in range(1, min(len(fields), len(headers))):
            records[j - 1][attr] = fields[j]
    by_order = {}
    for rec in records:
        order_key = rec.get('order.key', '')
        if order_key and order_key != '~':
            by_order.setdefault(order_key, []).append(rec)
    return by_order

def week_to_date(week_str):
    dt = datetime.strptime(week_str, "%G-W%V-%u")
    return dt.strftime("%Y-%m-%d")

def get_values(doc_data, order_key, field):
    values = []
    for rec in doc_data.get(order_key, []):
        val = rec.get(field, '')
        if val and val != '~':
            values.append(val)
    return values

def resolve_fact(docs_list, order_key, is_date=False):
    for doc_name, doc_data, field in docs_list:
        values = get_values(doc_data, order_key, field)
        if values:
            if len(set(values)) > 1:
                return "CONFLICT"
            val = values[0]
            if is_date:
                val = week_to_date(val)
            return [val, doc_name]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]
    doc_names = ['invoices', 'payments', 'purchase_orders', 'receipts', 'requisitions', 'warehouse_scans']
    docs = {}
    for fname in doc_names:
        fpath = os.path.join(dir_path, fname + '.tsv')
        docs[fname] = parse_tsv(fpath) if os.path.exists(fpath) else {}
    po_numbers = sorted(set(k for d in docs.values() for k in d))
    result = {}
    for po in po_numbers:
        result[f'pa.three_way_match::{po}'] = {
            'invoice amount': resolve_fact([('invoices', docs['invoices'], 'bill.value.usd')], po),
            'order amount': resolve_fact([('purchase_orders', docs['purchase_orders'], 'order.commit.usd')], po),
            'quantity received': resolve_fact([('receipts', docs['receipts'], 'goodsin.units')], po),
            'quantity invoiced': resolve_fact([('invoices', docs['invoices'], 'bill.qty.units')], po),
        }
    for po in po_numbers:
        result[f'pa.paid_in_window::{po}'] = {
            'goods received': resolve_fact(
                [('receipts', docs['receipts'], 'goodsin.day.wk'),
                 ('warehouse_scans', docs['warehouse_scans'], 'scanner.hit.wk')], po, is_date=True),
            'payment date': resolve_fact([('payments', docs['payments'], 'funds.out.wk')], po, is_date=True),
            'payment due': resolve_fact([('invoices', docs['invoices'], 'bill.deadline.wk')], po, is_date=True),
        }
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
