import sys
import os
import json
from datetime import date

def parse_week_date(s):
    parts = s.split('-W')
    year = int(parts[0])
    rest = parts[1].split('-')
    week = int(rest[0])
    day = int(rest[1])
    d = date.fromisocalendar(year, week, day)
    return d.isoformat()

def parse_file(filepath):
    with open(filepath, 'r') as f:
        lines = f.read().splitlines()

    header = None
    data_lines = []
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if header is None:
            header = line
        else:
            data_lines.append(line)

    if header is None:
        return {}

    attrs = {}
    for line in data_lines:
        parts = line.split('\t')
        attr = parts[0]
        values = parts[1:]
        attrs[attr] = values

    if 'order.key' not in attrs:
        return {}

    order_key_values = attrs['order.key']

    result = {}
    for attr, values in attrs.items():
        result[attr] = {}
        for i, v in enumerate(values):
            if i >= len(order_key_values):
                break
            ok = order_key_values[i]
            if ok == '~' or ok == '':
                continue
            if v == '~' or v == '':
                continue
            result[attr].setdefault(ok, []).append(v)

    return result

def resolve_fact(data, doc_name, attr, order_key, transform=None):
    if attr not in data:
        return ("absent", None, None)
    vals = data[attr].get(order_key)
    if vals is None or len(vals) == 0:
        return ("absent", None, None)
    transformed = [transform(v) if transform else v for v in vals]
    unique = set(transformed)
    if len(unique) > 1:
        return ("conflict", None, doc_name)
    return ("value", transformed[0], doc_name)

def fact_result(r):
    if r[0] == "value":
        return [r[1], r[2]]
    elif r[0] == "conflict":
        return "CONFLICT"
    else:
        return "ABSENT"

def main():
    dir_path = sys.argv[1]

    invoices = parse_file(os.path.join(dir_path, 'invoices.tsv'))
    payments = parse_file(os.path.join(dir_path, 'payments.tsv'))
    purchase_orders = parse_file(os.path.join(dir_path, 'purchase_orders.tsv'))
    receipts = parse_file(os.path.join(dir_path, 'receipts.tsv'))
    warehouse_scans = parse_file(os.path.join(dir_path, 'warehouse_scans.tsv'))

    output = {}

    for po_num in range(40201, 40217):
        entity = f"PO-{po_num}"

        # pa.three_way_match
        pair_id = f"pa.three_way_match::{entity}"
        facts = {}

        facts["invoice amount"] = fact_result(
            resolve_fact(invoices, "invoices", "bill.value.usd", entity))
        facts["order amount"] = fact_result(
            resolve_fact(purchase_orders, "purchase_orders", "order.commit.usd", entity))
        facts["quantity received"] = fact_result(
            resolve_fact(receipts, "receipts", "goodsin.units", entity))
        facts["quantity invoiced"] = fact_result(
            resolve_fact(invoices, "invoices", "bill.qty.units", entity))

        output[pair_id] = facts

        # pa.paid_in_window
        pair_id = f"pa.paid_in_window::{entity}"
        facts = {}

        r = resolve_fact(receipts, "receipts", "goodsin.day.wk", entity, transform=parse_week_date)
        if r[0] == "absent":
            r = resolve_fact(warehouse_scans, "warehouse_scans", "scanner.hit.wk", entity, transform=parse_week_date)
        facts["goods received"] = fact_result(r)

        facts["payment date"] = fact_result(
            resolve_fact(payments, "payments", "funds.out.wk", entity, transform=parse_week_date))
        facts["payment due"] = fact_result(
            resolve_fact(invoices, "invoices", "bill.deadline.wk", entity, transform=parse_week_date))

        output[pair_id] = facts

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
