import sys
import os
import json
from decimal import Decimal

def parse_file(filepath):
    records = []
    with open(filepath, 'r') as f:
        lines = f.readlines()
    header = None
    for line in lines:
        line = line.rstrip('\n').rstrip('\r')
        if not line.strip():
            continue
        if line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
        else:
            fields = line.split('|')
            if len(fields) == len(header):
                records.append(dict(zip(header, fields)))
    return records

def transform(v, kind):
    if kind == 'date':
        m, d, y = v.split('/')
        return f"{y}-{m}-{d}"
    elif kind == 'money':
        return str(Decimal(v))
    else:
        return v

def resolve_fact(entity, data, doc_specs):
    for doc_name, field_name, kind in doc_specs:
        if doc_name not in data:
            continue
        raw_values = []
        for r in data[doc_name]:
            if r.get('PURCHASE_DOCUMENT_KEY') == entity:
                v = r.get(field_name, '')
                if v != '':
                    raw_values.append(v)
        if not raw_values:
            continue
        transformed = [transform(v, kind) for v in raw_values]
        unique = set(transformed)
        if len(unique) == 1:
            return [transformed[0], doc_name]
        else:
            return "CONFLICT"
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    data = {}
    for fname in ['invoices', 'payments', 'purchase_orders', 'receipts', 'requisitions', 'warehouse_scans']:
