    result = {}

    for entity in entities:
        pair_id = f'pa.three_way_match::{entity}'
        result[pair_id] = {
            'invoice amount': resolve_fact(entity, data, [('invoices', 'VENDOR_BILLED_TOTAL', 'money')]),
