```python
import sys
import os
import json
from collections import defaultdict

def parse_file(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r') as f:
        lines = f.readlines()
    header = None
    data_lines = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
        else:
            data_lines.append(line.split('|'))
    if header is None:
        return []
    rows = []
    for parts in data_lines:
        if len(parts) != len(header):
            continue
        rows.append(dict(zip(header, parts)))
    return rows

def collect_values(rows, key_col, value_col):
    result = defaultdict(list)
    for row in rows:
        key = row.get(key_col, '').strip()
        val = row.get(value_col, '').strip()
        if key and val:
            result[key].append(val)
    return result

def resolve_value(values_list):
    if not values_list:
        return ('absent', None)
    unique = set(values_list)
    if len(unique) == 1:
        return ('value', values_list[0])
    return ('conflict', None)

def convert_date(mmddyyyy):
    parts = mmddyyyy.split('/')
    if len(parts) == 3:
        m, d, y = parts
        return f"{y}-{m.zfill(2)}-{d.zfill(2)}"
    return mmddyyyy

def get_fact(values_dict, po, doc_name, converter=None):
    status, val = resolve_value(values_dict.get(po, []))
    if status == 'value':
        if converter:
            val = converter(val)
        return [val, doc_name]
    elif status == 'conflict':
        return 'CONFLICT'
    return 'ABSENT'

def get_fact_with_fallback(primary_dict, fallback_dict, po, primary_doc, fallback_doc, converter=None):
    status, val = resolve_value(primary_dict.get(po, []))
    if status == 'value':
        if converter:
            val = converter(val)
        return [val, primary_doc]
    elif status == 'conflict':
        return 'CONFLICT'
    status2, val2 = resolve_value(fallback_dict.get(po, []))
    if status2 == 'value':
        if converter:
            val2 = converter(val2)
        return [val2, fallback_doc]
    elif status2 == 'conflict':
        return 'CONFLICT'
    return 'ABSENT'

def main():
    dir_path = sys.argv[1]
    invoices = parse_file(os.path.join(dir_path, 'invoices.txt'))
    payments = parse_file(os.path.join(dir_path, 'payments.txt'))
    purchase_orders = parse_file(os.path.join(dir_path, 'purchase_orders.txt'))
    receipts = parse_file(os.path.join(dir_path, 'receipts.txt'))
    warehouse_scans = parse_file(os.path.join(dir_path, 'warehouse_scans.txt'))
    requisitions = parse_file(os.path.join(dir_path, 'requisitions.txt'))

    all_pos = set()
    for rows in [invoices, payments, purchase_orders, receipts, warehouse_scans, requisitions]:
        for row in rows:
            po = row.get('PURCHASE_DOCUMENT_KEY', '').strip()
            if po:
                all_pos.add(po)
    sorted_pos = sorted(all_pos)

    invoice_amount = collect_values(invoices, 'PURCHASE_DOCUMENT_KEY', 'VENDOR_BILLED_TOTAL')
    quantity_invoiced = collect_values(invoices, 'PURCHASE_DOCUMENT_KEY', 'BILLED_UNIT_COUNT')
    payment_due = collect_values(invoices, 'PURCHASE_DOCUMENT_KEY', 'NET_DUE_DAY')
    order_amount = collect_values(purchase_orders, 'PURCHASE_DOCUMENT_KEY', 'ORDER_NET_VALUE')
    quantity_received = collect_values(receipts, 'PURCHASE_DOCUMENT_KEY', 'GR_ACCEPTED_UNITS')
    goods_received_receipts = collect_values(receipts, 'PURCHASE_DOCUMENT_KEY', 'GR_POSTING_DAY')
    payment_date = collect_values(payments, 'PURCHASE_DOCUMENT_KEY', 'DISBURSEMENT_CLEARED_DAY')
    goods_received_warehouse = collect_values(warehouse_scans, 'PURCHASE_DOCUMENT_KEY', 'INBOUND_DOOR_EVENT_DAY')

    result = {}
    for po in sorted_pos:
        twm = {}
        twm['invoice amount'] = get_fact(invoice_amount, po, 'invoices')
        twm['order amount'] = get_fact(order_amount, po, 'purchase_orders')
        twm['quantity received'] = get_fact(quantity_received, po, 'receipts')
        twm['quantity invoiced'] = get_fact(quantity_invoiced, po, 'invoices')
        result[f'pa.three_way_match::{po}'] = twm
    for po in sorted_pos:
        piw = {}
        piw['goods received'] = get_fact_with_fallback(
            goods_received_receipts, goods_received_warehouse, po, 'receipts', 'warehouse_scans', convert_date)
        piw['payment date'] = get_fact(payment_date, po, 'payments', convert_date)
        piw['payment due'] = get_fact(payment_due, po, 'invoices', convert_date)
        result[f'pa.paid_in_window::{po}'] = piw

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
