import sys
import os
import re
import json
from html import unescape
from decimal import Decimal

def strip_tags(text):
    return re.sub(r'<[^>]+>', '', text)

def parse_sheets(html_text):
    sheets = []
    article_pattern = re.compile(r'<article class="sheet"[^>]*>(.*?)</article>', re.DOTALL)
    for article_match in article_pattern.finditer(html_text):
        article_content = article_match.group(1)
        fields = {}
        row_pattern = re.compile(r'<tr>\s*<th>(.*?)</th>\s*<td([^>]*)>(.*?)</td>\s*</tr>', re.DOTALL)
        for row_match in row_pattern.finditer(article_content):
            th = unescape(strip_tags(row_match.group(1))).strip()
            td_attrs = row_match.group(2)
            td_raw = row_match.group(3)
            if 'void' in td_attrs:
                fields[th] = None
            else:
                td = unescape(strip_tags(td_raw)).strip()
                fields[th] = td if td else None
        po = fields.get("Procurement reference")
        sheets.append({"po": po, "fields": fields})
    return sheets

def parse_amount(text):
    text = text.replace("USD", "").replace(",", "").strip()
    try:
        return str(Decimal(text).quantize(Decimal('0.01')))
    except Exception:
        return None

def parse_units(text):
    text = re.sub(r'\s*pcs\s*', '', text).strip()
    return text if text else None

MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12,
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}

def parse_date(text):
    m = re.match(r'\w+\.\s*,?\s*([A-Za-z]+)\.?\s+(\d+),?\s+(\d{4})', text)
    if m:
        month = MONTHS.get(m.group(1).lower())
        if month:
            return f"{int(m.group(3)):04d}-{month:02d}-{int(m.group(2)):02d}"
    return None

def build_field_data(sheets, field_name, parse_func):
    data = {}
    for sheet in sheets:
        po = sheet["po"]
        if po is None:
            continue
        raw = sheet["fields"].get(field_name)
        if raw is None:
            continue
        parsed = parse_func(raw)
        if parsed is not None:
            data.setdefault(po, []).append(parsed)
    return data

def main():
    dir_path = sys.argv[1]

    doc_files = {
        "invoices": "invoices.html",
        "payments": "payments.html",
        "purchase_orders": "purchase_orders.html",
        "receipts": "receipts.html",
        "warehouse_scans": "warehouse_scans.html",
        "requisitions": "requisitions.html",
    }

    doc_sheets = {}
    all_pos = set()
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                sheets = parse_sheets(f.read())
            doc_sheets[doc_name] = sheets
            for sheet in sheets:
                if sheet["po"]:
                    all_pos.add(sheet["po"])
        except FileNotFoundError:
            doc_sheets[doc_name] = []

    fd = {}
    fd["invoices"] = {
        "Invoice grand total": build_field_data(doc_sheets.get("invoices", []), "Invoice grand total", parse_amount),
        "Units charged": build_field_data(doc_sheets.get("invoices", []), "Units charged", parse_units),
        "Payment deadline": build_field_data(doc_sheets.get("invoices", []), "Payment deadline", parse_date),
    }
    fd["purchase_orders"] = {
        "Total order value": build_field_data(doc_sheets.get("purchase_orders", []), "Total order value", parse_amount),
    }
    fd["receipts"] = {
        "Units counted on delivery": build_field_data(doc_sheets.get("receipts", []), "Units counted on delivery", parse_units),
        "Delivery booked": build_field_data(doc_sheets.get("receipts", []), "Delivery booked", parse_date),
    }
    fd["payments"] = {
        "Funds released": build_field_data(doc_sheets.get("payments", []), "Funds released", parse_date),
    }
    fd["warehouse_scans"] = {
        "Dock scanner stamp": build_field_data(doc_sheets.get("warehouse_scans", []), "Dock scanner stamp", parse_date),
    }

    rules = {
        "pa.three_way_match": {
            "invoice amount": {"doc": "invoices", "field": "Invoice grand total"},
            "order amount": {"doc": "purchase_orders", "field": "Total order value"},
            "quantity received": {"doc": "receipts", "field": "Units counted on delivery"},
            "quantity invoiced": {"doc": "invoices", "field": "Units charged"},
        },
        "pa.paid_in_window": {
            "goods received": {"doc": "receipts", "field": "Delivery booked",
                               "fallback_doc": "warehouse_scans", "fallback_field": "Dock scanner stamp"},
            "payment date": {"doc": "payments", "field": "Funds released"},
            "payment due": {"doc": "invoices", "field": "Payment deadline"},
        },
    }

    all_pos = sorted(all_pos)
    output = {}
    for rule_name in ["pa.three_way_match", "pa.paid_in_window"]:
        for po in all_pos:
            pair_id = f"{rule_name}::{po}"
            result = {}
            for fact_name, spec in rules[rule_name].items():
                doc = spec["doc"]
                field = spec["field"]
                values = fd[doc][field].get(po, [])
                if not values:
                    if "fallback_doc" in spec:
                        fb_doc = spec["fallback_doc"]
                        fb_field = spec["fallback_field"]
                        fb_values = fd[fb_doc][fb_field].get(po, [])
                        if not fb_values:
                            result[fact_name] = "ABSENT"
                        elif len(set(fb_values)) == 1:
                            result[fact_name] = [fb_values[0], fb_doc]
                        else:
                            result[fact_name] = "CONFLICT"
                    else:
                        result[fact_name] = "ABSENT"
                elif len(set(values)) == 1:
                    result[fact_name] = [values[0], doc]
                else:
                    result[fact_name] = "CONFLICT"
            output[pair_id] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
