import os

def clean_html(text):
    text = re.sub(r'<[^>]+>', '', text)
    text = text.replace('&mdash;', '\u2014')
    text = text.replace('&amp;', '&')
    text = text.replace('&nbsp;', ' ')
    text = text.replace('&rsaquo;', '\u203a')
    text = text.replace('&middot;', '\u00b7')
    text = text.replace('&ndash;', '\u2013')
    return text.strip()

def parse_sheets(html_text):
    pattern = re.compile(r'<article class="sheet"[^>]*>(.*?)</article>', re.DOTALL)
    return [m.group(1) for m in pattern.finditer(html_text)]

def parse_fields(sheet_html):
    fields = {}
    row_pattern = re.compile(r'<tr>\s*<th[^>]*>(.*?)</th>\s*(<td[^>]*>)(.*?)</td>\s*</tr>', re.DOTALL)
    for m in row_pattern.finditer(sheet_html):
        label = clean_html(m.group(1))
        td_open = m.group(2)
        value_html = m.group(3)
        if 'void' in td_open:
            fields[label] = None
        else:
            fields[label] = clean_html(value_html)
    return fields

def build_doc_data(html_text):
    po_to_fields = {}
    for sheet in parse_sheets(html_text):
        fields = parse_fields(sheet)
        po = fields.get('Procurement reference')
        if po:
            po_to_fields.setdefault(po, []).append(fields)
    return po_to_fields

def parse_amount(text):
    if text is None:
        return None
    m = re.search(r'USD\s*([\d,]+\.?\d*)', text)
    if m:
        return m.group(1).replace(',', '')
    return None

def parse_units(text):
    if text is None:
        return None
    m = re.search(r'(\d+)\s*pcs', text)
    if m:
        return m.group(1)
    return None

MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}

def parse_date(text):
    if text is None:
        return None
    m = re.search(r'([A-Za-z]+)\.?\s+(\d{1,2}),?\s*(\d{4})', text)
    if m:
        month_name = m.group(1).lower()[:3]
        day = int(m.group(2))
        year = int(m.group(3))
        month = MONTHS.get(month_name)
        if month:
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None

def extract_fact(doc_data, doc_name, po, field_name, parser_func):
    if po not in doc_data:
        return 'ABSENT'
    values = []
    for fields in doc_data[po]:
        raw = fields.get(field_name)
        if raw is None:
            continue
        parsed = parser_func(raw)
        if parsed is not None:
            values.append(parsed)
    if not values:
        return 'ABSENT'
    if len(set(values)) == 1:
        return [values[0], doc_name]
    return 'CONFLICT'

def extract_with_fallback(primary_data, primary_doc, primary_field,
                           fallback_data, fallback_doc, fallback_field,
                           parser_func, po):
    result = extract_fact(primary_data, primary_doc, po, primary_field, parser_func)
    if result == 'ABSENT' and fallback_data is not None:
        result = extract_fact(fallback_data, fallback_doc, po, fallback_field, parser_func)
    return result

def main():
    dir_path = sys.argv[1]

    def read_file(name):
        path = os.path.join(dir_path, name)
        with open(path, 'r', encoding='utf-8') as f:
            return f.read()

    invoices_data = build_doc_data(read_file('invoices.html'))
    payments_data = build_doc_data(read_file('payments.html'))
    purchase_orders_data = build_doc_data(read_file('purchase_orders.html'))
    receipts_data = build_doc_data(read_file('receipts.html'))
    warehouse_scans_data = build_doc_data(read_file('warehouse_scans.html'))
    requisitions_data = build_doc_data(read_file('requisitions.html'))

    all_pos = set()
    for dd in [invoices_data, payments_data, purchase_orders_data,
               receipts_data, warehouse_scans_data, requisitions_data]:
        all_pos.update(dd.keys())
    pos = sorted(all_pos)

    result = {}

    for po in pos:
        result[f"pa.three_way_match::{po}"] = {
            "invoice amount": extract_fact(invoices_data, "invoices", po, "Invoice grand total", parse_amount),
            "order amount": extract_fact(purchase_orders_data, "purchase_orders", po, "Total order value", parse_amount),
            "quantity received": extract_fact(receipts_data, "receipts", po, "Units counted on delivery", parse_units),
            "quantity invoiced": extract_fact(invoices_data, "invoices", po, "Units charged", parse_units),
        }
        result[f"pa.paid_in_window::{po}"] = {
            "goods received": extract_with_fallback(
                receipts_data, "receipts", "Delivery booked",
                warehouse_scans_data, "warehouse_scans", "Dock scanner stamp",
                parse_date, po),
            "payment date": extract_fact(payments_data, "payments", po, "Funds released", parse_date),
            "payment due": extract_fact(invoices_data, "invoices", po, "Payment deadline", parse_date),
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
