import re
import os
import sys
import json
from datetime import date, timedelta
from decimal import Decimal

CONFLICT = object()


def parse_sql_file(filepath):
    """Parse a SQL file and return a list of records (dicts)."""
    try:
        with open(filepath, 'r', encoding='utf-8-sig') as f:
            content = f.read()
    except FileNotFoundError:
        return []

    insert_pattern = re.compile(
        r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);',
        re.IGNORECASE | re.DOTALL
    )

    records = []
    for match in insert_pattern.finditer(content):
        cols_str = match.group(1)
        values_str = match.group(2)

        cols = [c.strip() for c in cols_str.split(',')]
        tuples = parse_tuples(values_str)

        for tuple_str in tuples:
            vals = parse_values(tuple_str)
            if len(vals) == len(cols):
                record = dict(zip(cols, vals))
                records.append(record)

    return records


def parse_tuples(values_str):
    """Parse a string of SQL value tuples."""
    tuples = []
    i = 0
    while i < len(values_str):
        while i < len(values_str) and values_str[i] in ' \t\n\r,':
            i += 1
        if i >= len(values_str):
            break
        if values_str[i] != '(':
            i += 1
            continue

        i += 1
        current_tuple = ''
        in_quote = False
        depth = 1
        while i < len(values_str) and depth > 0:
            char = values_str[i]
            if char == "'":
                if i + 1 < len(values_str) and values_str[i + 1] == "'":
                    current_tuple += "''"
                    i += 2
                    continue
                in_quote = not in_quote
                current_tuple += char
            elif char == '(' and not in_quote:
                depth += 1
                current_tuple += char
            elif char == ')' and not in_quote:
                depth -= 1
                if depth > 0:
                    current_tuple += char
            else:
                current_tuple += char
            i += 1

        tuples.append(current_tuple)

    return tuples


def parse_values(vals_str):
    """Parse a comma-separated list of SQL values."""
    values = []
    current = ''
    in_quote = False
    i = 0
    while i < len(vals_str):
        char = vals_str[i]
        if char == "'":
            if i + 1 < len(vals_str) and vals_str[i + 1] == "'":
                current += "''"
                i += 2
                continue
            in_quote = not in_quote
            current += char
        elif char == ',' and not in_quote:
            values.append(current.strip())
            current = ''
        else:
            current += char
        i += 1
    if current.strip():
        values.append(current.strip())

    parsed = []
    for v in values:
        if v.upper() == 'NULL':
            parsed.append(None)
        elif v.startswith("'") and v.endswith("'"):
            parsed.append(v[1:-1].replace("''", "'"))
        else:
            try:
                parsed.append(int(v))
            except ValueError:
                try:
                    parsed.append(float(v))
                except ValueError:
                    parsed.append(v)

    return parsed


def epd_to_date(epd):
    """Convert epoch day to YYYY-MM-DD string."""
    d = date(1970, 1, 1) + timedelta(days=epd)
    return d.isoformat()


def cents_to_usd(cents):
    """Convert cents to USD string."""
    return f"{Decimal(str(cents)) / Decimal(100):.2f}"


def format_units(val):
    """Format a quantity in units."""
    if isinstance(val, float) and val == int(val):
        return str(int(val))
    return str(val)


def get_fact_values(records, ord_code, field):
    """Get all non-NULL values for a field for a given ord_code."""
    values = []
    for record in records:
        if record.get('ord_code') == ord_code:
            val = record.get(field)
            if val is not None:
                values.append(val)
    return values


def resolve_fact(sources, ord_code):
    """Resolve a fact from a list of sources.
    Each source is (records, doc_name, field).
    Returns (value, doc_name) or (None, None) for ABSENT or (CONFLICT, None) for CONFLICT."""
    for records, doc_name, field in sources:
        values = get_fact_values(records, ord_code, field)
        if values:
            distinct = set(values)
            if len(distinct) > 1:
                return (CONFLICT, None)
            return (values[0], doc_name)
    return (None, None)


def main():
    dir_path = sys.argv[1]

    invoices = parse_sql_file(os.path.join(dir_path, 'invoices.sql'))
    payments = parse_sql_file(os.path.join(dir_path, 'payments.sql'))
    purchase_orders = parse_sql_file(os.path.join(dir_path, 'purchase_orders.sql'))
    receipts = parse_sql_file(os.path.join(dir_path, 'receipts.sql'))
    warehouse_scans = parse_sql_file(os.path.join(dir_path, 'warehouse_scans.sql'))

    result = {}

    for po_num in range(40401, 40417):
        ord_code = f'PO-{po_num}'
        pair_id = f'pa.three_way_match::{ord_code}'
        result[pair_id] = {}

        val, doc = resolve_fact([(invoices, 'invoices', 'billed_cents')], ord_code)
        if val is None:
            result[pair_id]['invoice amount'] = "ABSENT"
        elif val is CONFLICT:
            result[pair_id]['invoice amount'] = "CONFLICT"
        else:
            result[pair_id]['invoice amount'] = [cents_to_usd(val), doc]

        val, doc = resolve_fact([(purchase_orders, 'purchase_orders', 'commit_cents')], ord_code)
        if val is None:
            result[pair_id]['order amount'] = "ABSENT"
        elif val is CONFLICT:
            result[pair_id]['order amount'] = "CONFLICT"
        else:
            result[pair_id]['order amount'] = [cents_to_usd(val), doc]

        val, doc = resolve_fact([(receipts, 'receipts', 'dock_unit_ct')], ord_code)
        if val is None:
            result[pair_id]['quantity received'] = "ABSENT"
        elif val is CONFLICT:
            result[pair_id]['quantity received'] = "CONFLICT"
        else:
            result[pair_id]['quantity received'] = [format_units(val), doc]

        val, doc = resolve_fact([(invoices, 'invoices', 'billed_unit_ct')], ord_code)
        if val is None:
            result[pair_id]['quantity invoiced'] = "ABSENT"
        elif val is CONFLICT:
            result[pair_id]['quantity invoiced'] = "CONFLICT"
        else:
            result[pair_id]['quantity invoiced'] = [format_units(val), doc]

    for po_num in range(40401, 40417):
        ord_code = f'PO-{po_num}'
        pair_id = f'pa.paid_in_window::{ord_code}'
        result[pair_id] = {}

        val, doc = resolve_fact([
            (receipts, 'receipts', 'goods_in_epd'),
