import re
import sys
import json
import os
from datetime import date, timedelta
from decimal import Decimal

def parse_sql_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    rows = []
    for tbl, cols_str, vals_str in re.findall(
        r'INSERT INTO\s+(\w+)\s*\(([^)]+)\)\s*VALUES\s*(.*?);',
        content, re.DOTALL | re.IGNORECASE
    ):
        cols = [c.strip() for c in cols_str.split(',')]
        for tup in re.findall(r'\(([^)]+)\)', vals_str):
            rows.append(dict(zip(cols, parse_values(tup))))
    return rows

def parse_values(tup_str):
    values = []
    current = ''
    in_quote = False
    for ch in tup_str:
        if ch == "'":
            in_quote = not in_quote
            current += ch
        elif ch == ',' and not in_quote:
            values.append(current.strip())
            current = ''
        else:
            current += ch
    if current.strip():
        values.append(current.strip())
    result = []
    for v in values:
        v = v.strip()
        if v.upper() == 'NULL':
            result.append(None)
        elif v.startswith("'") and v.endswith("'"):
            result.append(v[1:-1])
        else:
            try:
                result.append(int(v))
            except ValueError:
                try:
                    result.append(float(v))
                except ValueError:
                    result.append(v)
    return result

def epd_to_date(epd):
    return (date(1970, 1, 1) + timedelta(days=int(epd))).isoformat()

def cents_to_usd(cents):
    return str(Decimal(int(cents)) / Decimal(100))

def to_units(x):
    return str(int(x))

def get_values(rows, ord_code, column):
    return [row[column] for row in rows
            if row.get('ord_code') == ord_code and row.get(column) is not None]

def resolve_fact(doc_rows, doc_name, ord_code, column, transform,
                 fallback_rows=None, fallback_name=None, fallback_column=None):
    values = get_values(doc_rows, ord_code, column)
    if values:
        transformed = {transform(v) for v in values}
        if len(transformed) == 1:
            return [transformed.pop(), doc_name]
        return "CONFLICT"
    if fallback_rows is not None and fallback_column is not None:
        values = get_values(fallback_rows, ord_code, fallback_column)
        if values:
            transformed = {transform(v) for v in values}
            if len(transformed) == 1:
                return [transformed.pop(), fallback_name]
            return "CONFLICT"
    return "ABSENT"

def main():
    dir_path = sys.argv[1]
    doc_files = {
        'invoices': 'invoices.sql',
        'payments': 'payments.sql',
        'purchase_orders': 'purchase_orders.sql',
        'receipts': 'receipts.sql',
        'requisitions': 'requisitions.sql',
        'warehouse_scans': 'warehouse_scans.sql',
    }
