        ord_code = f'PO-{po_num}'
        result[f'pa.three_way_match::{ord_code}'] = {
            'invoice amount': resolve_fact(
                docs['invoices'], 'invoices', ord_code, 'billed_cents', cents_to_usd),
            'order amount': resolve_fact(
                docs['purchase_orders'], 'purchase_orders', ord_code, 'commit_cents', cents_to_usd),
            'quantity received': resolve_fact(
                docs['receipts'], 'receipts', ord_code, 'dock_unit_ct', to_units),
            'quantity invoiced': resolve_fact(
                docs['invoices'], 'invoices', ord_code, 'billed_unit_ct', to_units),
        }
    for po_num in range(40501, 40517):
        ord_code = f'PO-{po_num}'
        result[f'pa.paid_in_window::{ord_code}'] = {
            'goods received': resolve_fact(
