                fallback_rows=docs['warehouse_scans'],
                fallback_name='warehouse_scans',
                fallback_column='scanner_hit_epd'),
            'payment date': resolve_fact(
                docs['payments'], 'payments', ord_code, 'funds_out_epd', epd_to_date),
            'payment due': resolve_fact(
                docs['invoices'], 'invoices', ord_code, 'pay_deadline_epd', epd_to_date),
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
