import sys
import os
import json
from decimal import Decimal

def parse_edi_loops(content):
    raw = content.replace('\r\n', '\n').replace('\r', '\n').replace('\n', '')
    raw_segments = raw.split('~')
    raw_segments = [s for s in raw_segments if s.strip()]

    loops = []
    current_loop = None

    for seg in raw_segments:
        parts = [p.strip() for p in seg.split('*')]
        tag = parts[0]

        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            current_loop.append(parts)

    if current_loop is not None:
        loops.append(current_loop)

    return loops

def extract_po(loop):
    for seg in loop:
        if len(seg) >= 3 and seg[0] == 'REF' and seg[1] == 'PO':
            return seg[2]
    return None

def format_tds(val):
    d = Decimal(val) / Decimal(100)
    return f"{d:.2f}"

def format_amt(val):
    d = Decimal(val)
    return f"{d:.2f}"

def format_date(val):
    return f"{val[0:4]}-{val[4:6]}-{val[6:8]}"

def match_tds(seg):
    if seg[0] == 'TDS' and len(seg) >= 2:
        return format_tds(seg[1])
    return None

def match_qty_d1(seg):
    if seg[0] == 'QTY' and len(seg) >= 3 and seg[1] == 'D1':
        return seg[2]
    return None

def match_amt_tt(seg):
    if seg[0] == 'AMT' and len(seg) >= 3 and seg[1] == 'TT':
        return format_amt(seg[2])
    return None

def match_qty_rc(seg):
    if seg[0] == 'QTY' and len(seg) >= 3 and seg[1] == 'RC':
        return seg[2]
    return None

def match_dtp(seg, qualifier):
    if seg[0] == 'DTP' and len(seg) >= 4 and seg[1] == qualifier and seg[2] == 'D8':
        return format_date(seg[3])
    return None

def get_values_for_po(loops, po_key, matcher):
    values = []
    for loop in loops:
        if extract_po(loop) == po_key:
            for seg in loop:
                v = matcher(seg)
                if v is not None:
                    values.append(v)
    return values

def resolve_value(values):
    if not values:
        return None
    unique = set(values)
    if len(unique) == 1:
        return values[0]
    return "CONFLICT"

def resolve_fact(values, doc):
    if not values:
        return "ABSENT"
    result = resolve_value(values)
    if result == "CONFLICT":
        return "CONFLICT"
    return [result, doc]

def resolve_fact_with_fallback(primary_values, fallback_values, primary_doc, fallback_doc):
    if primary_values:
        result = resolve_value(primary_values)
        if result == "CONFLICT":
            return "CONFLICT"
        return [result, primary_doc]
    if fallback_values:
        result = resolve_value(fallback_values)
        if result == "CONFLICT":
            return "CONFLICT"
        return [result, fallback_doc]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    files = {
        'invoices': 'invoices.edi',
        'payments': 'payments.edi',
        'purchase_orders': 'purchase_orders.edi',
        'receipts': 'receipts.edi',
        'warehouse_scans': 'warehouse_scans.edi',
    }

    contents = {}
    for name, filename in files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            with open(filepath, 'r', encoding='utf-8') as f:
                contents[name] = f.read()
        else:
            contents[name] = ''

    loops = {}
    for name, content in contents.items():
        loops[name] = parse_edi_loops(content)

    pos = [f"PO-405{i:02d}" for i in range(1, 17)]

    result = {}

    for po in pos:
        twm_key = f"pa.three_way_match::{po}"
        result[twm_key] = {}

        values = get_values_for_po(loops['invoices'], po, match_tds)
        result[twm_key]["invoice amount"] = resolve_fact(values, "invoices")

        values = get_values_for_po(loops['purchase_orders'], po, match_amt_tt)
        result[twm_key]["order amount"] = resolve_fact(values, "purchase_orders")

        values = get_values_for_po(loops['receipts'], po, match_qty_rc)
        result[twm_key]["quantity received"] = resolve_fact(values, "receipts")

        values = get_values_for_po(loops['invoices'], po, match_qty_d1)
        result[twm_key]["quantity invoiced"] = resolve_fact(values, "invoices")

        piw_key = f"pa.paid_in_window::{po}"
        result[piw_key] = {}

        primary_values = get_values_for_po(loops['receipts'], po, lambda seg: match_dtp(seg, '050'))
        fallback_values = get_values_for_po(loops['warehouse_scans'], po, lambda seg: match_dtp(seg, '945'))
        result[piw_key]["goods received"] = resolve_fact_with_fallback(
            primary_values, fallback_values, "receipts", "warehouse_scans")

        values = get_values_for_po(loops['payments'], po, lambda seg: match_dtp(seg, '234'))
        result[piw_key]["payment date"] = resolve_fact(values, "payments")

        values = get_values_for_po(loops['invoices'], po, lambda seg: match_dtp(seg, '481'))
        result[piw_key]["payment due"] = resolve_fact(values, "invoices")

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
