            continue
        else:
            current.append(parts)
    if current is not None:
        loops.append(current)
    return loops


def get_seg_values(loop, tag, qual=None):
    vals = []
    for parts in loop:
        if parts[0] != tag:
            continue
        if qual is not None:
            if len(parts) < 2 or parts[1] != qual:
                continue
        if tag == 'REF':
            vals.append(parts[2] if len(parts) > 2 else '')
        elif tag == 'QTY':
            vals.append(parts[2] if len(parts) > 2 else '')
        elif tag == 'DTP':
            vals.append(parts[3] if len(parts) > 3 else '')
        elif tag == 'AMT':
            vals.append(parts[2] if len(parts) > 2 else '')
        elif tag == 'TDS':
            vals.append(parts[1] if len(parts) > 1 else '')
    return vals


def get_po(loop):
    vals = get_seg_values(loop, 'REF', 'PO')
    return vals[0] if vals else None


def build_po_values(loops, tag, qual=None):
    result = defaultdict(list)
    for loop in loops:
        po = get_po(loop)
        if po is None:
            continue
        vals = get_seg_values(loop, tag, qual)
        for v in vals:
            result[po].append(v)
    return result


def norm_tds(raw):
    try:
        return f"{int(raw.strip()) / 100:.2f}"
    except Exception:
        return raw.strip()


def norm_amt(raw):
    try:
        return f"{float(raw.strip()):.2f}"
    except Exception:
        return raw.strip()


def norm_qty(raw):
    return raw.strip()


def norm_date(raw):
    raw = raw.strip()
    if len(raw) == 8 and raw.isdigit():
        return f"{raw[0:4]}-{raw[4:6]}-{raw[6:8]}"
    return raw


def resolve_fact(po, doc_chain):
    for doc_name, po_values, norm_fn in doc_chain:
        if po in po_values and po_values[po]:
            raw_vals = po_values[po]
            normalized = [norm_fn(v) for v in raw_vals]
            unique = set(normalized)
            if len(unique) == 1:
                return [normalized[0], doc_name]
            else:
                return 'CONFLICT'
    return 'ABSENT'


def main():
    dir_path = sys.argv[1]

    file_map = {
        'invoices': 'invoices.edi',
        'payments': 'payments.edi',
        'purchase_orders': 'purchase_orders.edi',
        'receipts': 'receipts.edi',
        'requisitions': 'requisitions.edi',
        'warehouse_scans': 'warehouse_scans.edi',
    }

    docs = {}
    all_pos = set()
    for doc_name, fname in file_map.items():
        path = os.path.join(dir_path, fname)
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                docs[doc_name] = parse_edi(f.read())
            for loop in docs[doc_name]:
                po = get_po(loop)
                if po:
                    all_pos.add(po)
        else:
            docs[doc_name] = []

    inv_tds = build_po_values(docs['invoices'], 'TDS')
    inv_qty_d1 = build_po_values(docs['invoices'], 'QTY', 'D1')
    inv_dtp_481 = build_po_values(docs['invoices'], 'DTP', '481')
    po_amt_tt = build_po_values(docs['purchase_orders'], 'AMT', 'TT')
    rec_qty_rc = build_po_values(docs['receipts'], 'QTY', 'RC')
    rec_dtp_050 = build_po_values(docs['receipts'], 'DTP', '050')
    pay_dtp_234 = build_po_values(docs['payments'], 'DTP', '234')
    wh_dtp_945 = build_po_values(docs['warehouse_scans'], 'DTP', '945')

    fact_chains = {
        'pa.three_way_match': {
            'invoice amount': [('invoices', inv_tds, norm_tds)],
            'order amount': [('purchase_orders', po_amt_tt, norm_amt)],
            'quantity received': [('receipts', rec_qty_rc, norm_qty)],
            'quantity invoiced': [('invoices', inv_qty_d1, norm_qty)],
        },
        'pa.paid_in_window': {
            'goods received': [('receipts', rec_dtp_050, norm_date),
                               ('warehouse_scans', wh_dtp_945, norm_date)],
            'payment date': [('payments', pay_dtp_234, norm_date)],
            'payment due': [('invoices', inv_dtp_481, norm_date)],
        },
    }

    output = {}
    for rule in ['pa.three_way_match', 'pa.paid_in_window']:
        for po in sorted(all_pos):
            pair_id = f"{rule}::{po}"
            fact_obj = {}
            for fact_name, chain in fact_chains[rule].items():
                fact_obj[fact_name] = resolve_fact(po, chain)
            output[pair_id] = fact_obj

    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
