import sys
import os
import re
import json

MONTHS = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4, 'may': 5, 'june': 6,
    'july': 7, 'august': 8, 'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

def parse_date(s):
    s = s.strip().rstrip('.').strip()
    m = re.match(r'([A-Za-z]+)\s+(\d+)(?:st|nd|rd|th)?,?\s+(\d{4})', s)
    if m:
        month = MONTHS.get(m.group(1).lower())
        if month:
            return f"{m.group(3)}-{month:02d}-{int(m.group(2)):02d}"
    m = re.match(r'(\d+)(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})', s)
    if m:
        month = MONTHS.get(m.group(2).lower())
        if month:
            return f"{m.group(3)}-{month:02d}-{int(m.group(1)):02d}"
    return None

def parse_amount(s):
    return str(int(s.replace(',', '')))

def split_messages(text):
    parts = re.split(r'={70,}', text)
    messages = []
    for part in parts:
        part = part.strip()
        if part and 'Subject:' in part:
            messages.append(part)
    return messages

def get_po(msg):
    m = re.search(r'Subject:.*?(PO-\d+)', msg)
    return m.group(1) if m else None

def parse_invoices(text):
    result = {}
    for msg in split_messages(text):
        po = get_po(msg)
        if not po:
            continue
        if po not in result:
            result[po] = {'invoice_amount': [], 'quantity_invoiced': [], 'payment_due': []}
        m = re.search(r'(?:Invoice total is|bill comes to)\s+\$?([\d,]+)(?:\s+dollars)?\s+(?:all told|in total)', msg)
        if m:
            result[po]['invoice_amount'].append(parse_amount(m.group(1)))
        m = re.search(r'Bill lists (\d+) (?:units|pieces) as the chargeable count', msg)
        if m:
            result[po]['quantity_invoiced'].append(m.group(1))
        m = re.search(r'They charged us for (\d+) (?:units|pieces) on that bill', msg)
        if m:
            result[po]['quantity_invoiced'].append(m.group(1))
        m = re.search(r'Payment has to go out by (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['payment_due'].append(d)
        m = re.search(r'The bill must be settled no later than (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['payment_due'].append(d)
    return result

def parse_purchase_orders(text):
    result = {}
    for msg in split_messages(text):
        po = get_po(msg)
        if not po:
            continue
        if po not in result:
            result[po] = {'order_amount': []}
        m = re.search(r'(?:The PO was raised for|Committed value on the PO is)\s+\$?([\d,]+)(?:\s+dollars)?\s+(?:in total|overall)', msg)
        if m:
            result[po]['order_amount'].append(parse_amount(m.group(1)))
    return result

def parse_receipts(text):
    result = {}
    for msg in split_messages(text):
        po = get_po(msg)
        if not po:
            continue
        if po not in result:
            result[po] = {'quantity_received': [], 'goods_received': []}
        m = re.search(r'Receiving tallied (\d+) (?:units|pieces) off the truck', msg)
        if m:
            result[po]['quantity_received'].append(m.group(1))
        m = re.search(r'We counted (\d+) (?:units|pieces) on arrival', msg)
        if m:
            result[po]['quantity_received'].append(m.group(1))
        m = re.search(r'It was booked in on (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['goods_received'].append(d)
        m = re.search(r'The delivery was logged as received on (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['goods_received'].append(d)
    return result

def parse_payments(text):
    result = {}
    for msg in split_messages(text):
        po = get_po(msg)
        if not po:
            continue
        if po not in result:
            result[po] = {'payment_date': []}
        m = re.search(r'We sent the money on (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['payment_date'].append(d)
        m = re.search(r'Funds were released to the vendor on (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['payment_date'].append(d)
    return result

def parse_warehouse_scans(text):
    result = {}
    for msg in split_messages(text):
        po = get_po(msg)
        if not po:
            continue
        if po not in result:
            result[po] = {'goods_received': []}
        m = re.search(r'Scanner stamp at the dock reads (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['goods_received'].append(d)
        m = re.search(r'The dock scanner picked it up on (.+?)\.', msg)
        if m:
            d = parse_date(m.group(1))
            if d:
                result[po]['goods_received'].append(d)
    return result

def resolve_simple(doc_data, po, fact_key, doc_name):
    if po in doc_data and fact_key in doc_data[po]:
        values = doc_data[po][fact_key]
        if values:
            if len(set(values)) == 1:
                return [values[0], doc_name]
            else:
                return "CONFLICT"
    return "ABSENT"

def resolve_with_fallback(primary_data, po, primary_key, primary_name, fallback_data, fallback_key, fallback_name):
    if po in primary_data and primary_key in primary_data[po]:
        values = primary_data[po][primary_key]
        if values:
            if len(set(values)) == 1:
                return [values[0], primary_name]
            else:
                return "CONFLICT"
    if po in fallback_data and fallback_key in fallback_data[po]:
        values = fallback_data[po][fallback_key]
        if values:
            if len(set(values)) == 1:
                return [values[0], fallback_name]
            else:
                return "CONFLICT"
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    def read_file(filename):
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            with open(filepath, 'r', encoding='utf-8') as f:
                return f.read()
        return ''

    invoices_data = parse_invoices(read_file('invoices.txt'))
    payments_data = parse_payments(read_file('payments.txt'))
    purchase_orders_data = parse_purchase_orders(read_file('purchase_orders.txt'))
    receipts_data = parse_receipts(read_file('receipts.txt'))
    warehouse_scans_data = parse_warehouse_scans(read_file('warehouse_scans.txt'))

    output = {}
    pos = [f'PO-406{i:02d}' for i in range(1, 17)]

    for po in pos:
        twm_key = f'pa.three_way_match::{po}'
        output[twm_key] = {
            'invoice amount': resolve_simple(invoices_data, po, 'invoice_amount', 'invoices'),
            'order amount': resolve_simple(purchase_orders_data, po, 'order_amount', 'purchase_orders'),
            'quantity received': resolve_simple(receipts_data, po, 'quantity_received', 'receipts'),
            'quantity invoiced': resolve_simple(invoices_data, po, 'quantity_invoiced', 'invoices'),
        }

        piw_key = f'pa.paid_in_window::{po}'
        output[piw_key] = {
            'goods received': resolve_with_fallback(
                receipts_data, po, 'goods_received', 'receipts',
                warehouse_scans_data, 'goods_received', 'warehouse_scans'
            ),
            'payment date': resolve_simple(payments_data, po, 'payment_date', 'payments'),
            'payment due': resolve_simple(invoices_data, po, 'payment_due', 'invoices'),
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
