import sys
import json
import os
from datetime import date, timedelta

def week_date_to_date(week_date_str):
    parts = week_date_str.split('-')
    year = int(parts[0])
    week = int(parts[1][1:])
    day = int(parts[2])
    jan4 = date(year, 1, 4)
    week1_monday = jan4 - timedelta(days=jan4.weekday())
    result = week1_monday + timedelta(weeks=week - 1, days=day - 1)
    return result.isoformat()

def parse_tsv(filepath):
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        lines = f.read().splitlines()
    data_lines = [l for l in lines if not l.startswith('#') and l.strip()]
    if not data_lines:
        return {}
    header = data_lines[0].split('\t')
    record_names = header[1:]
    records = {}
    for rec_name in record_names:
        records[rec_name] = {}
    for line in data_lines[1:]:
        fields = line.split('\t')
        if not fields or not fields[0]:
            continue
        attr = fields[0]
        for i, val in enumerate(fields[1:]):
            if i < len(record_names):
                records[record_names[i]][attr] = val
    return records

def group_by_order_key(records):
    groups = {}
    for rec_name, rec in records.items():
        order_key = rec.get('order.key')
        if order_key and order_key != '~' and order_key != '':
            groups.setdefault(order_key, []).append(rec)
    return groups

def get_values(record_list, attr):
    values = []
    for rec in record_list:
        if attr in rec and rec[attr] != '~' and rec[attr] != '':
            values.append(rec[attr])
    return values

def convert_value(val, attr):
    if attr.endswith('.wk'):
        return week_date_to_date(val)
    return val

def resolve_fact(doc_groups, doc_name, attr, entity):
    record_list = doc_groups.get(doc_name, {}).get(entity, [])
    values = get_values(record_list, attr)
    if not values:
        return None
    converted = [convert_value(v, attr) for v in values]
    if len(set(converted)) > 1:
        return "CONFLICT"
    return [converted[0], doc_name]

def main():
    dir_path = sys.argv[1]
    files = {
        'invoices': 'invoices.tsv',
        'payments': 'payments.tsv',
        'purchase_orders': 'purchase_orders.tsv',
        'receipts': 'receipts.tsv',
        'requisitions': 'requisitions.tsv',
        'warehouse_scans': 'warehouse_scans.tsv',
    }
    doc_groups = {}
    for doc_name, filename in files.items():
        filepath = os.path.join(dir_path, filename)
        records = parse_tsv(filepath)
        doc_groups[doc_name] = group_by_order_key(records)
    rules = {
        'pa.three_way_match': {
            'invoice amount': [('invoices', 'bill.value.usd')],
            'order amount': [('purchase_orders', 'order.commit.usd')],
            'quantity received': [('receipts', 'goodsin.units')],
            'quantity invoiced': [('invoices', 'bill.qty.units')],
        },
        'pa.paid_in_window': {
            'goods received': [('receipts', 'goodsin.day.wk'), ('warehouse_scans', 'scanner.hit.wk')],
            'payment date': [('payments', 'funds.out.wk')],
            'payment due': [('invoices', 'bill.deadline.wk')],
        },
    }
    all_order_keys = set()
    for doc_name in doc_groups:
        for order_key in doc_groups[doc_name]:
            all_order_keys.add(order_key)
    all_order_keys = sorted(all_order_keys)
    rules_order = ['pa.three_way_match', 'pa.paid_in_window']
    result = {}
    for rule_name in rules_order:
        for entity in all_order_keys:
            pair_id = f"{rule_name}::{entity}"
            result[pair_id] = {}
            for fact_name, sources in rules[rule_name].items():
                resolved = None
                for doc_name, attr in sources:
                    resolved = resolve_fact(doc_groups, doc_name, attr, entity)
                    if resolved is not None:
                        break
                if resolved is None:
                    result[pair_id][fact_name] = "ABSENT"
                else:
                    result[pair_id][fact_name] = resolved
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
