import sys
import os
import json
from datetime import date, timedelta

def parse_tsv(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r') as f:
        content = f.read()
    lines = content.split('\n')
    data_lines = [l for l in lines if l.strip() and not l.startswith('#')]
    if not data_lines:
        return []
    header = data_lines[0].split('\t')
    records = []
    for line in data_lines[1:]:
        fields = line.split('\t')
        record = {}
        for i, attr in enumerate(header):
            record[attr] = fields[i] if i < len(fields) else ''
        records.append(record)
    return records

def get_values_by_key(records, key_attr, value_attr):
    result = {}
    for rec in records:
        key = rec.get(key_attr, '')
        value = rec.get(value_attr, '')
        if key and value and value != '~':
            if key not in result:
                result[key] = []
            result[key].append(value)
    return result

def get_all_keys(records, key_attr):
    result = set()
    for rec in records:
        key = rec.get(key_attr, '')
        if key:
            result.add(key)
    return result

def resolve_value(values_list):
    if not values_list:
        return None
    unique = set(values_list)
    if len(unique) == 1:
        return values_list[0]
    return "CONFLICT"

def convert_week_date(s):
    parts = s.split('-')
    iso_year = int(parts[0])
    week = int(parts[1][1:])
    day = int(parts[2])
    jan4 = date(iso_year, 1, 4)
    week1_monday = jan4 - timedelta(days=jan4.weekday())
    target = week1_monday + timedelta(weeks=week-1, days=day-1)
    return target.isoformat()

def make_fact_value(resolved, convert_fn=None, doc_name=None):
    if resolved is None:
        return "ABSENT"
    if resolved == "CONFLICT":
        return "CONFLICT"
    val = convert_fn(resolved) if convert_fn else resolved
    return [val, doc_name]

def main():
    dir_path = sys.argv[1]

    invoices = parse_tsv(os.path.join(dir_path, 'invoices.tsv'))
    payments = parse_tsv(os.path.join(dir_path, 'payments.tsv'))
    purchase_orders = parse_tsv(os.path.join(dir_path, 'purchase_orders.tsv'))
    receipts = parse_tsv(os.path.join(dir_path, 'receipts.tsv'))
    requisitions = parse_tsv(os.path.join(dir_path, 'requisitions.tsv'))
    warehouse_scans = parse_tsv(os.path.join(dir_path, 'warehouse_scans.tsv'))

    inv_amount = get_values_by_key(invoices, 'order.key', 'bill.value.usd')
    inv_qty = get_values_by_key(invoices, 'order.key', 'bill.qty.units')
    inv_deadline = get_values_by_key(invoices, 'order.key', 'bill.deadline.wk')
    pay_date = get_values_by_key(payments, 'order.key', 'funds.out.wk')
    po_amount = get_values_by_key(purchase_orders, 'order.key', 'order.commit.usd')
    rcpt_date = get_values_by_key(receipts, 'order.key', 'goodsin.day.wk')
    rcpt_qty = get_values_by_key(receipts, 'order.key', 'goodsin.units')
    scan_date = get_values_by_key(warehouse_scans, 'order.key', 'scanner.hit.wk')

    all_pos = set()
    for records in [invoices, payments, purchase_orders, receipts, requisitions, warehouse_scans]:
        all_pos.update(get_all_keys(records, 'order.key'))

    result = {}

    for po in sorted(all_pos):
        twm = {}
        twm["invoice amount"] = make_fact_value(resolve_value(inv_amount.get(po, [])), doc_name="invoices")
        twm["order amount"] = make_fact_value(resolve_value(po_amount.get(po, [])), doc_name="purchase_orders")
        twm["quantity received"] = make_fact_value(resolve_value(rcpt_qty.get(po, [])), doc_name="receipts")
        twm["quantity invoiced"] = make_fact_value(resolve_value(inv_qty.get(po, [])), doc_name="invoices")
        result[f"pa.three_way_match::{po}"] = twm

        piw = {}
        rcpt_resolved = resolve_value(rcpt_date.get(po, []))
        if rcpt_resolved is None:
            piw["goods received"] = make_fact_value(resolve_value(scan_date.get(po, [])), convert_fn=convert_week_date, doc_name="warehouse_scans")
        else:
            piw["goods received"] = make_fact_value(rcpt_resolved, convert_fn=convert_week_date, doc_name="receipts")
        piw["payment date"] = make_fact_value(resolve_value(pay_date.get(po, [])), convert_fn=convert_week_date, doc_name="payments")
        piw["payment due"] = make_fact_value(resolve_value(inv_deadline.get(po, [])), convert_fn=convert_week_date, doc_name="invoices")
        result[f"pa.paid_in_window::{po}"] = piw

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
