import sys
import os
import json

def parse_file(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()
    header = None
    rows = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if header is None:
            header = [h.strip() for h in line.split('|')]
            continue
        fields = [f.strip() for f in line.split('|')]
        if len(fields) == len(header):
            row = dict(zip(header, fields))
            rows.append(row)
    return rows

def convert_date(date_str):
    if not date_str:
        return None
    parts = date_str.split('/')
    if len(parts) == 3:
        return f"{parts[2]}-{parts[0].zfill(2)}-{parts[1].zfill(2)}"
    return date_str

def resolve_fact(sources, po_key):
    for doc_name, rows, field, is_date in sources:
        values = []
        for row in rows:
            if row.get('PURCHASE_DOCUMENT_KEY') == po_key:
                val = row.get(field, '')
                if val:
                    values.append(val)
        if values:
            unique_values = set(values)
            if len(unique_values) > 1:
                return 'CONFLICT'
            val = values[0]
            if is_date:
                val = convert_date(val)
            return [val, doc_name]
    return 'ABSENT'

def main():
    dir_path = sys.argv[1]

