import sys
import os
import json

def load_records(filepath):
    """Parse a pipe-delimited disclosure file into a list of dicts."""
    records = []
    with open(filepath, 'r') as f:
        lines = f.readlines()
    header = None
    for line in lines:
        line = line.rstrip('\n').rstrip('\r')
        if not line or line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
            continue
        parts = line.split('|')
        if len(parts) != len(header):
            continue
        records.append(dict(zip(header, parts)))
    return records

def convert_value(v, fact_type):
    """Convert a raw string to the required output format."""
    if fact_type == 'date':
        parts = v.split('/')
        if len(parts) == 3:
            return f"{parts[2]}-{parts[0]}-{parts[1]}"
        return v
    return v

def get_fact_value(records_by_doc, po, doc_name, column, fact_type,
                   fallback_doc=None, fallback_column=None):
    """
    Return (value, document) for the given PO and fact, or "ABSENT" or "CONFLICT".
    """
    # Primary document
    vals = []
    for rec in records_by_doc.get(doc_name, []):
        if rec.get('PURCHASE_DOCUMENT_KEY') == po:
            v = rec.get(column, '')
            if v != '':
                vals.append(v)
    distinct = set(vals)
    if len(distinct) == 1:
        return (convert_value(list(distinct)[0], fact_type), doc_name)
    elif len(distinct) > 1:
        return "CONFLICT"
    else:
        # Fallback document
        if fallback_doc is not None:
            vals_f = []
            for rec in records_by_doc.get(fallback_doc, []):
                if rec.get('PURCHASE_DOCUMENT_KEY') == po:
                    v = rec.get(fallback_column, '')
                    if v != '':
                        vals_f.append(v)
            distinct_f = set(vals_f)
            if len(distinct_f) == 1:
                return (convert_value(list(distinct_f)[0], fact_type), fallback_doc)
            elif len(distinct_f) > 1:
                return "CONFLICT"
            else:
                return "ABSENT"
        else:
            return "ABSENT"

def main():
    if len(sys.argv) != 2:
        print("Usage: program <directory>", file=sys.stderr)
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_files = {
        'invoices': 'invoices.txt',
        'payments': 'payments.txt',
        'purchase_orders': 'purchase_orders.txt',
        'receipts': 'receipts.txt',
        'requisitions': 'requisitions.txt',
        'warehouse_scans': 'warehouse_scans.txt',
    }

    records_by_doc = {}
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            records_by_doc[doc_name] = load_records(filepath)
        else:
            records_by_doc[doc_name] = []

    # Collect all purchase document keys appearing in any file
    all_pos = set()
    for records in records_by_doc.values():
        for rec in records:
            po = rec.get('PURCHASE_DOCUMENT_KEY')
            if po:
                all_pos.add(po)

    def po_sort_key(po):
        try:
            return int(po.split('-')[1])
        except Exception:
            return 0

    sorted_pos = sorted(all_pos, key=po_sort_key)

    rules = {
        'pa.three_way_match': {
            'invoice amount': {'doc': 'invoices', 'column': 'VENDOR_BILLED_TOTAL', 'type': 'amount'},
            'order amount': {'doc': 'purchase_orders', 'column': 'ORDER_NET_VALUE', 'type': 'amount'},
            'quantity received': {'doc': 'receipts', 'column': 'GR_ACCEPTED_UNITS', 'type': 'quantity'},
            'quantity invoiced': {'doc': 'invoices', 'column': 'BILLED_UNIT_COUNT', 'type': 'quantity'},
        },
        'pa.paid_in_window': {
            'goods received': {'doc': 'receipts', 'column': 'GR_POSTING_DAY', 'type': 'date',
                               'fallback_doc': 'warehouse_scans', 'fallback_column': 'INBOUND_DOOR_EVENT_DAY'},
            'payment date': {'doc': 'payments', 'column': 'DISBURSEMENT_CLEARED_DAY', 'type': 'date'},
            'payment due': {'doc': 'invoices', 'column': 'NET_DUE_DAY', 'type': 'date'},
        }
    }

    output = {}
    for rule_name, facts in rules.items():
        for po in sorted_pos:
            pair_id = f"{rule_name}::{po}"
            fact_results = {}
            for fact_name, spec in facts.items():
                res = get_fact_value(
                    records_by_doc, po, spec['doc'], spec['column'], spec['type'],
                    spec.get('fallback_doc'), spec.get('fallback_column')
                )
                if res == "ABSENT":
                    fact_results[fact_name] = "ABSENT"
                elif res == "CONFLICT":
                    fact_results[fact_name] = "CONFLICT"
                else:
                    value, doc = res
                    fact_results[fact_name] = [value, doc]
            output[pair_id] = fact_results

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
