import sys
import os
import re
import json

MONTHS = {
    'Jan': 1, 'January': 1,
    'Feb': 2, 'February': 2,
    'Mar': 3, 'March': 3,
    'Apr': 4, 'April': 4,
    'May': 5,
    'Jun': 6, 'June': 6,
    'Jul': 7, 'July': 7,
    'Aug': 8, 'August': 8,
    'Sep': 9, 'September': 9,
    'Oct': 10, 'October': 10,
    'Nov': 11, 'November': 11,
    'Dec': 12, 'December': 12,
}


def parse_date(s):
    m = re.search(r'([A-Za-z]+)\.?\s+(\d+),\s+(\d{4})', s)
    if not m:
        return None
    month_name = m.group(1)
    day = int(m.group(2))
    year = int(m.group(3))
    month = MONTHS.get(month_name)
    if month is None:
        return None
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_usd(s):
    return s.replace('USD', '').replace(',', '').strip()


def parse_units(s):
    m = re.search(r'(\d+)', s)
    return m.group(1) if m else None


def convert(raw, ftype):
    if ftype == 'usd':
        return parse_usd(raw)
    elif ftype == 'units':
        return parse_units(raw)
    elif ftype == 'date':
        return parse_date(raw)
    return raw


def parse_file(path):
    try:
        with open(path, encoding='utf-8') as f:
            content = f.read()
    except (IOError, OSError):
        return []
    sheets = []
    for article_match in re.finditer(r'<article class="sheet"[^>]*>(.*?)</article>', content, re.DOTALL):
        block = article_match.group(1)
        po_match = re.search(r'<th>Procurement reference</th><td><strong>([^<]+)</strong></td>', block)
        if not po_match:
            continue
        po = po_match.group(1).strip()
        fields = {}
        for row_match in re.finditer(r'<tr><th>([^<]+)</th><td([^>]*)>(.*?)</td></tr>', block, re.DOTALL):
            caption = row_match.group(1).strip()
            attrs = row_match.group(2)
            value_html = row_match.group(3)
            if 'void' in attrs:
                fields[caption] = None
            else:
                value_text = re.sub(r'<[^>]+>', '', value_html).strip()
                fields[caption] = value_text
        sheets.append((po, fields))
    return sheets


def build_doc_data(directory):
    doc_files = {
        'invoices': 'invoices.html',
        'payments': 'payments.html',
        'purchase_orders': 'purchase_orders.html',
        'receipts': 'receipts.html',
        'warehouse_scans': 'warehouse_scans.html',
    }
    doc_data = {}
    for doc_name, filename in doc_files.items():
        path = os.path.join(directory, filename)
        sheets = parse_file(path)
        po_map = {}
        for po, fields in sheets:
            po_map.setdefault(po, []).append(fields)
        doc_data[doc_name] = po_map
    return doc_data


def get_values(doc_data, doc, caption, po):
    sheets = doc_data.get(doc, {}).get(po, [])
    values = []
    for sheet_fields in sheets:
        v = sheet_fields.get(caption)
        if v is not None:
            values.append(v)
    return values


def resolve_fact(doc_data, spec, po):
    doc = spec['doc']
    caption = spec['caption']
    ftype = spec['type']
    values = get_values(doc_data, doc, caption, po)

    if len(values) > 0:
        converted = [convert(v, ftype) for v in values]
        distinct = set(converted)
        if len(distinct) == 1:
            return [converted[0], doc]
        else:
            return "CONFLICT"

    if 'fallback_doc' in spec:
        fb_doc = spec['fallback_doc']
        fb_caption = spec['fallback_caption']
        fb_values = get_values(doc_data, fb_doc, fb_caption, po)
        if len(fb_values) > 0:
            converted = [convert(v, ftype) for v in fb_values]
            distinct = set(converted)
            if len(distinct) == 1:
                return [converted[0], fb_doc]
            else:
                return "CONFLICT"

    return "ABSENT"


FACTS = {
    'pa.three_way_match': {
        'invoice amount': {'doc': 'invoices', 'caption': 'Invoice grand total', 'type': 'usd'},
        'order amount': {'doc': 'purchase_orders', 'caption': 'Total order value', 'type': 'usd'},
        'quantity received': {'doc': 'receipts', 'caption': 'Units counted on delivery', 'type': 'units'},
        'quantity invoiced': {'doc': 'invoices', 'caption': 'Units charged', 'type': 'units'},
    },
    'pa.paid_in_window': {
        'goods received': {'doc': 'receipts', 'caption': 'Delivery booked', 'type': 'date',
                           'fallback_doc': 'warehouse_scans', 'fallback_caption': 'Dock scanner stamp'},
        'payment date': {'doc': 'payments', 'caption': 'Funds released', 'type': 'date'},
        'payment due': {'doc': 'invoices', 'caption': 'Payment deadline', 'type': 'date'},
    },
}


def main():
    directory = sys.argv[1]
    doc_data = build_doc_data(directory)

    pairs = []
    for i in range(1, 17):
        po = f'PO-409{i:02d}'
        pairs.append(f'pa.three_way_match::{po}')
    for i in range(1, 17):
        po = f'PO-409{i:02d}'
        pairs.append(f'pa.paid_in_window::{po}')

    output = {}
    for pair_id in pairs:
        rule, po = pair_id.split('::', 1)
        fact_obj = {}
        for fact_name, spec in FACTS[rule].items():
            fact_obj[fact_name] = resolve_fact(doc_data, spec, po)
        output[pair_id] = fact_obj

    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
