from html.parser import HTMLParser


class SheetParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.sheets = []
        self.in_sheet = False
        self.in_table = False
        self.in_row = False
        self.in_th = False
        self.in_td = False
        self.current_sheet = None
        self.current_th_text = ""
        self.current_td_text = ""
        self.current_field_name = None
        self.td_is_void = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag == "article" and "sheet" in attrs_dict.get("class", "").split():
            self.in_sheet = True
            self.current_sheet = {"po": None, "fields": {}}
        elif tag == "table" and self.in_sheet:
            self.in_table = True
        elif tag == "tr" and self.in_table:
            self.in_row = True
            self.current_th_text = ""
            self.current_td_text = ""
            self.current_field_name = None
            self.td_is_void = False
        elif tag == "th" and self.in_row:
            self.in_th = True
        elif tag == "td" and self.in_row:
            self.in_td = True
            if "void" in attrs_dict.get("class", "").split():
                self.td_is_void = True

    def handle_endtag(self, tag):
        if tag == "article" and self.in_sheet:
            self.in_sheet = False
            if self.current_sheet:
                self.sheets.append(self.current_sheet)
                self.current_sheet = None
        elif tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "tr" and self.in_row:
            self.in_row = False
            if self.current_field_name is not None and self.current_sheet is not None:
                value = self.current_td_text.strip()
                if self.td_is_void or "left blank" in value:
                    value = None
                self.current_sheet["fields"][self.current_field_name] = value
                if self.current_field_name == "Procurement reference" and value:
                    po_match = re.search(r'PO-\d+', value)
                    if po_match:
                        self.current_sheet["po"] = po_match.group(0)
        elif tag == "th" and self.in_th:
            self.in_th = False
            self.current_field_name = self.current_th_text.strip()
        elif tag == "td" and self.in_td:
            self.in_td = False

    def handle_data(self, data):
        if self.in_th:
            self.current_th_text += data
        elif self.in_td:
            self.current_td_text += data


def parse_amount(text):
    if not text:
        return None
    match = re.search(r'([\d,]+\.?\d*)', text)
    if match:
        return match.group(1).replace(',', '')
    return None


def parse_quantity(text):
    if not text:
        return None
    match = re.search(r'(\d+)', text)
    if match:
        return match.group(1)
    return None


MONTHS = {
    'January': 1, 'Jan': 1, 'February': 2, 'Feb': 2, 'March': 3, 'Mar': 3,
    'April': 4, 'Apr': 4, 'May': 5, 'June': 6, 'Jun': 6, 'July': 7, 'Jul': 7,
    'August': 8, 'Aug': 8, 'September': 9, 'Sep': 9, 'Sept': 9,
    'October': 10, 'Oct': 10, 'November': 11, 'Nov': 11, 'December': 12, 'Dec': 12
}


def parse_date(text):
    if not text:
        return None
    match = re.search(r'(\w+)\.?,?\s+(\w+)\.?\s+(\d+),\s+(\d{4})', text)
    if match:
        month_name = match.group(2)
        day = int(match.group(3))
        year = int(match.group(4))
        month = MONTHS.get(month_name)
        if month:
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None


FACT_RULES = {
    "pa.three_way_match": {
        "invoice amount": {
            "primary_doc": "invoices",
