            "fallback_field": None,
        },
    },
    "pa.paid_in_window": {
        "goods received": {
            "primary_doc": "receipts",
            "field": "Delivery booked",
            "parser": parse_date,
            "fallback_doc": "warehouse_scans",
            "fallback_field": "Dock scanner stamp",
        },
