    "pa.paid_in_window::PO-41009", "pa.paid_in_window::PO-41010",
    "pa.paid_in_window::PO-41011", "pa.paid_in_window::PO-41012",
    "pa.paid_in_window::PO-41013", "pa.paid_in_window::PO-41014",
    "pa.paid_in_window::PO-41015", "pa.paid_in_window::PO-41016",
]


def extract_fact(doc_sheets, po, field_name, parser_func):
    values = []
    for sheet in doc_sheets:
        if sheet["po"] == po:
            raw = sheet["fields"].get(field_name)
            if raw is not None:
                parsed = parser_func(raw)
                if parsed is not None:
                    values.append(parsed)
    if not values:
        return None
    if len(set(values)) > 1:
        return "CONFLICT"
    return values[0]


def main():
    directory = sys.argv[1]
    docs = {}
    for filename in ['invoices.html', 'payments.html', 'purchase_orders.html',
                     'receipts.html', 'warehouse_scans.html', 'requisitions.html']:
        filepath = os.path.join(directory, filename)
        if os.path.exists(filepath):
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
            p = SheetParser()
            p.feed(content)
            doc_name = filename.replace('.html', '')
            docs[doc_name] = p.sheets

    result = {}
    for pair_id in PAIRS:
        rule_name, po = pair_id.split("::")
        pair_result = {}
        for fact_name, fr in FACT_RULES[rule_name].items():
            primary_doc = fr["primary_doc"]
            field = fr["field"]
            parser_func = fr["parser"]
            if primary_doc in docs:
                primary_result = extract_fact(docs[primary_doc], po, field, parser_func)
            else:
                primary_result = None
            if primary_result == "CONFLICT":
                pair_result[fact_name] = "CONFLICT"
            elif primary_result is not None:
                pair_result[fact_name] = [primary_result, primary_doc]
            else:
                fb_doc = fr["fallback_doc"]
                fb_field = fr["fallback_field"]
                if fb_doc and fb_field and fb_doc in docs:
                    fb_result = extract_fact(docs[fb_doc], po, fb_field, parser_func)
                    if fb_result == "CONFLICT":
                        pair_result[fact_name] = "CONFLICT"
                    elif fb_result is not None:
                        pair_result[fact_name] = [fb_result, fb_doc]
                    else:
                        pair_result[fact_name] = "ABSENT"
                else:
                    pair_result[fact_name] = "ABSENT"
        result[pair_id] = pair_result

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
