import sys
import os
import re
import json
from datetime import date, timedelta

def epd_to_date(epd):
    return (date(1970, 1, 1) + timedelta(days=int(float(epd)))).isoformat()

def cents_to_usd(cents):
    return f"{int(float(cents)) / 100:.2f}"

def extract_tuples(s):
    """Extract tuples from VALUES section."""
    tuples = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '(':
            depth = 1
            j = i + 1
            in_string = False
            while j < n and depth > 0:
                if s[j] == "'" and not in_string:
                    in_string = True
                elif s[j] == "'" and in_string:
                    if j + 1 < n and s[j+1] == "'":
                        j += 1
                    else:
                        in_string = False
                elif not in_string:
                    if s[j] == '(':
                        depth += 1
                    elif s[j] == ')':
                        depth -= 1
                j += 1
            tuples.append(s[i+1:j-1])
            i = j
        else:
            i += 1
    return tuples

def parse_value_list(s):
    """Parse comma-separated values, handling quotes and NULL."""
    values = []
    i = 0
    n = len(s)
    while i < n:
        while i < n and s[i] in ' \t\n,':
            i += 1
        if i >= n:
            break
        if s[i] == "'":
            i += 1
            start = i
            while i < n:
                if s[i] == "'":
                    if i + 1 < n and s[i+1] == "'":
                        i += 2
                    else:
                        break
                else:
                    i += 1
            values.append(s[start:i])
            i += 1
        else:
            start = i
            while i < n and s[i] != ',':
                i += 1
            val = s[start:i].strip()
            if val == 'NULL':
                values.append(None)
            else:
                values.append(val)
    return values

def parse_sql(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r') as f:
        content = f.read()
    insert_pattern = r'INSERT INTO (\w+)\s*\(([^)]+)\)\s*VALUES\s*(.*?);'
    inserts = re.findall(insert_pattern, content, re.DOTALL)
    records = []
    for table_name, cols_str, vals_str in inserts:
        columns = [c.strip() for c in cols_str.split(',')]
        tuples = extract_tuples(vals_str)
        for tup_str in tuples:
            values = parse_value_list(tup_str)
            record = dict(zip(columns, values))
            records.append(record)
    return records

def get_values(records, ord_code, field):
    """Get all non-NULL values for a field for a given ord_code."""
    values = []
    for rec in records:
        if rec.get('ord_code') == ord_code:
            val = rec.get(field)
            if val is not None:
                values.append(val)
    return values

def resolve_fact(values):
    """Resolve a list of values to a single result."""
    if not values:
        return "ABSENT"
    unique = set(values)
    if len(unique) == 1:
        return values[0]
    return "CONFLICT"

def main():
    dir_path = sys.argv[1]
    invoices = parse_sql(os.path.join(dir_path, 'invoices.sql'))
    payments = parse_sql(os.path.join(dir_path, 'payments.sql'))
    purchase_orders = parse_sql(os.path.join(dir_path, 'purchase_orders.sql'))
    receipts = parse_sql(os.path.join(dir_path, 'receipts.sql'))
    warehouse_scans = parse_sql(os.path.join(dir_path, 'warehouse_scans.sql'))

    result = {}
    order_codes = [f'PO-410{i:02d}' for i in range(1, 17)]

    for oc in order_codes:
        twm_key = f'pa.three_way_match::{oc}'
        twm = {}

        vals = get_values(invoices, oc, 'billed_cents')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            twm['invoice amount'] = "ABSENT"
        elif resolved == "CONFLICT":
            twm['invoice amount'] = "CONFLICT"
        else:
            twm['invoice amount'] = [cents_to_usd(resolved), "invoices"]

        vals = get_values(purchase_orders, oc, 'commit_cents')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            twm['order amount'] = "ABSENT"
        elif resolved == "CONFLICT":
            twm['order amount'] = "CONFLICT"
        else:
            twm['order amount'] = [cents_to_usd(resolved), "purchase_orders"]

        vals = get_values(receipts, oc, 'dock_unit_ct')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            twm['quantity received'] = "ABSENT"
        elif resolved == "CONFLICT":
            twm['quantity received'] = "CONFLICT"
        else:
            twm['quantity received'] = [str(int(float(resolved))), "receipts"]

        vals = get_values(invoices, oc, 'billed_unit_ct')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            twm['quantity invoiced'] = "ABSENT"
        elif resolved == "CONFLICT":
            twm['quantity invoiced'] = "CONFLICT"
        else:
            twm['quantity invoiced'] = [str(int(float(resolved))), "invoices"]

        result[twm_key] = twm

    for oc in order_codes:
        piw_key = f'pa.paid_in_window::{oc}'
        piw = {}

        vals = get_values(receipts, oc, 'goods_in_epd')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            vals = get_values(warehouse_scans, oc, 'scanner_hit_epd')
            resolved = resolve_fact(vals)
            if resolved == "ABSENT":
                piw['goods received'] = "ABSENT"
            elif resolved == "CONFLICT":
                piw['goods received'] = "CONFLICT"
            else:
                piw['goods received'] = [epd_to_date(resolved), "warehouse_scans"]
        elif resolved == "CONFLICT":
            piw['goods received'] = "CONFLICT"
        else:
            piw['goods received'] = [epd_to_date(resolved), "receipts"]

        vals = get_values(payments, oc, 'funds_out_epd')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            piw['payment date'] = "ABSENT"
        elif resolved == "CONFLICT":
            piw['payment date'] = "CONFLICT"
        else:
            piw['payment date'] = [epd_to_date(resolved), "payments"]

        vals = get_values(invoices, oc, 'pay_deadline_epd')
        resolved = resolve_fact(vals)
        if resolved == "ABSENT":
            piw['payment due'] = "ABSENT"
        elif resolved == "CONFLICT":
            piw['payment due'] = "CONFLICT"
        else:
            piw['payment due'] = [epd_to_date(resolved), "invoices"]

        result[piw_key] = piw

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
